public int secondLargest(int[] nums) {
    long first = Long.MIN_VALUE, second = Long.MIN_VALUE;
    for (int x : nums) {
        if (x > first) {
            second = first;
            first = x;
        } else if (x > second && x != first) {
            second = x;
        }
    }
    return (int) second;
}

